import {OFFICIAL_DOMAINS,PERFORMANCE_BANDS,OFFICIAL_PRACTICE_URL,resultsGate,saveOfficialReport,setPracticeScoreSatisfied,bandLabel} from './results-logic.js?v=10';
import {localDate,validDate} from './planner.js?v=10';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pretty=d=>new Date(d+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'});
export function createResultsUI(context){
 const {getState,getProfile,save,render,toast}=context;let adding=false;
 const state=()=>getState();
 function form({required=false}={}){
  const p=getProfile(),prefs=state().studio.preferences||state().routine||{};
  return `<section class="results-entry settings-section"><div class="results-entry-heading"><h2>${required?'Start with your latest official results':'Add an official score report'}</h2>${!required?'<button class="text-button" data-action="results-cancel">Cancel</button>':''}</div><p>Use one actual SAT or full-length Bluebook SAT practice report. Enter the section scores and the performance band shown for each domain.</p><form id="official-report-form"><div class="settings-form-grid"><label>Report source<select name="source" required><option value="">Choose your report</option><option value="official-sat">Actual SAT</option><option value="official-bluebook">Official Bluebook SAT practice test</option></select></label><label>Test taken on<input name="date" type="date" max="${localDate()}" required></label><label>Math score<input name="math" type="number" min="200" max="800" step="10" required></label><label>Reading and Writing score<input name="readingWriting" type="number" min="200" max="800" step="10" required></label><label>Test name or number<input name="testName" type="text" maxlength="120" placeholder="For example, Bluebook Practice Test 4"></label><label>Your target total score<input name="goal" type="number" min="400" max="1600" step="10" value="${p.total||''}" placeholder="Optional"></label><label>Study focus<select name="scope">${['Both','Math','Reading and Writing'].map(x=>`<option ${x===(prefs.scope||'Both')?'selected':''}>${x}</option>`).join('')}</select></label><label>Next SAT date<input name="testDate" type="date" min="${localDate()}" value="${p.testDate&&p.testDate>localDate()?esc(p.testDate):''}"></label></div><p class="field-note">A future SAT date enables your calendar. Leave it blank if you haven’t booked a test.</p>${Object.entries(OFFICIAL_DOMAINS).map(([section,domains],s)=>`<fieldset class="results-domains"><legend>${esc(section)} domain bands</legend><div class="settings-form-grid">${domains.map((domain,d)=>`<label>${esc(domain.name)}<select name="band-${s}-${d}" required><option value="">Select the band on your report</option>${PERFORMANCE_BANDS[section].map(([a,b])=>`<option value="${a}-${b}">${a}–${b}</option>`).join('')}</select></label>`).join('')}</div></fieldset>`).join('')}<p class="field-note">Domain bands cover several skills. They guide the starting point; fresh practice checks which specific skills need work. Use a single test sitting, not a superscore.</p><p class="form-error" id="official-results-error" role="alert"></p><button class="primary" type="submit">Save results and build my path</button></form><p class="small muted">Your report is entered manually and saved on this device. <a href="https://satsuite.collegeboard.org/practice/my-practice-101" target="_blank" rel="noopener noreferrer">Find your Bluebook score report</a>.</p></section>`;
 }
 function gate(model){
  if(model.gate?.reason==='test-date-reached')return `<div class="path-home results-gate"><header class="path-page-heading"><div><h1>${model.testDate===localDate()?'Your SAT date is here':'Ready for your next test?'}</h1><p>Your scheduled date: ${esc(pretty(model.testDate))}</p></div></header><section class="settings-section"><h2>${model.testDate===localDate()?'Keep today light.':'Set your next SAT date.'}</h2><p>The roadmap has reached the test date you entered. Update your routine when you have another date, and add the new official report when it arrives.</p><button class="primary" data-action="path-setup">Edit test date</button><a class="secondary" href="#review">Review earlier work</a></section>${resume(model)}</div>`;
  return `<div class="path-home results-gate"><header class="path-page-heading"><div><h1>Your score report comes first.</h1><p>A useful study path starts with evidence of what you need to practice.</p></div></header><details class="results-first-test"><summary>Haven’t taken an official test yet?</summary><p>Take a full-length SAT practice test in Bluebook under its normal timing. Then return with the scores and domain bands from My Practice. The short diagnostics assembled inside Apple SAT do not replace that baseline.</p><a class="primary" href="${OFFICIAL_PRACTICE_URL}" target="_blank" rel="noopener noreferrer">Take an official Bluebook practice test</a></details>${form({required:true})}${resume(model)}</div>`;
 }
 function resume(model){const paused=model.tasks.find(t=>t.sessionId||t.examId);return paused?`<aside class="path-resume"><p>Your existing work is saved. You can resume it while preparing your score report.</p><button class="secondary" data-action="path-task" data-id="${esc(paused.id)}">Resume saved work</button></aside>`:'';}
 function roadmap(model){
  if(adding)return form();
  const r=model.roadmap,report=model.gate?.report;if(!r?.ready||!report)return '';
  const section=r.sections.find(s=>s.section===model.section)||r.sections[0],weak=section?.weakestDomains?.[0];
  return `<section class="results-basis"><div><p>Based on your ${report.source==='official-sat'?'SAT':'Bluebook practice'} report from ${esc(pretty(report.date))}: <strong>${report.total}</strong> total.</p>${weak?`<p class="small muted">${esc(section.section)} focus: ${esc(weak.name)}, ${esc(bandLabel(weak.band))}. Specific skill priorities are checked through practice.</p>`:''}</div><button class="text-button" data-action="results-add">Add newer results</button><details class="results-checkpoints"><summary>Official practice checkpoints</summary><p>Plan another full-length Bluebook test about every two weeks while preparing. Enter its report to refresh your path, even after you’ve reviewed every lesson.</p>${r.checkpoints.length?`<ol>${r.checkpoints.map(c=>`<li><strong>${esc(pretty(c.date))}</strong><span>Full-length Bluebook SAT and report update · about 2 h 24 min</span></li>`).join('')}</ol>`:`<p>${r.happyWithPracticeScore?'You’ve paused periodic tests because you’re happy with your practice score.':r.needsTestDate?'Add your next SAT date in Settings to schedule checkpoints.':'There is no full-test checkpoint before this test date. Use lighter review close to test day.'}</p>`}<p class="small muted">These intervals are adjustable app planning defaults. Practice and actual scores can differ in either direction; Apple SAT does not predict a scaled score.</p>${report.source==='official-bluebook'||state().studio.officialResults?.reports?.some(r=>r.source==='official-bluebook')?`<button class="secondary" data-action="results-satisfied">${r.happyWithPracticeScore?'Resume periodic official tests':'I’m happy with my practice score; pause full tests'}</button>`:''}<a class="text-button" href="${OFFICIAL_PRACTICE_URL}" target="_blank" rel="noopener noreferrer">Open official practice</a></details></section>`;
 }
 function settings(){const reports=state().studio.officialResults?.reports||[];return `<details class="settings-section settings-detail"><summary>Official SAT and Bluebook reports</summary><p>These reports guide Home. Broad domain bands are kept separate from exact-skill practice results.</p><button class="secondary" data-action="results-add">Add official test results</button>${[...reports].sort((a,b)=>b.date.localeCompare(a.date)).map(r=>`<details class="settings-diagnostic"><summary>${esc(pretty(r.date))} · ${r.source==='official-sat'?'SAT':'Bluebook'} · ${r.total}</summary><p>Math ${r.math}; Reading and Writing ${r.readingWriting}. ${esc(r.testName)}</p><ul>${Object.entries(r.domains).flatMap(([section,domains])=>Object.entries(domains).map(([name,band])=>`<li>${esc(section)} — ${esc(name)}: ${esc(bandLabel(band))}</li>`)).join('')}</ul></details>`).join('')||'<p class="small muted">No official test report entered yet.</p>'}</details>`;}
 function click(action){
  if(action==='results-add'||action==='score-add'){adding=true;location.hash='home';render();window.scrollTo({top:0});return true;}
  if(action==='results-cancel'){adding=false;render();return true;}
  if(action==='results-satisfied'){try{setPracticeScoreSatisfied(state(),!state().studio.officialResults?.happyWithPracticeScore);save();render();}catch(e){toast(e.message);}return true;}
  return false;
 }
 function submit(event){
  if(event.target.id!=='official-report-form')return false;event.preventDefault();
  try{
   const f=new FormData(event.target),domains={};
   Object.entries(OFFICIAL_DOMAINS).forEach(([section,rows],s)=>{domains[section]={};rows.forEach((d,i)=>domains[section][d.name]=String(f.get(`band-${s}-${i}`)||''));});
   const testDate=String(f.get('testDate')||''),goal=f.get('goal')===''?null:Number(f.get('goal'));
   if(testDate&&(!validDate(testDate)||testDate<=localDate()))throw Error('Enter your next SAT date after today, or leave it blank.');
   if(goal!==null&&(!Number.isInteger(goal)||goal<400||goal>1600||goal%10))throw Error('Enter a target from 400–1600 in steps of 10.');
   const scope=String(f.get('scope'));if(!['Both','Math','Reading and Writing'].includes(scope))throw Error('Choose a study focus.');
   const report=saveOfficialReport(state(),{source:f.get('source'),date:f.get('date'),testName:f.get('testName'),math:Number(f.get('math')),readingWriting:Number(f.get('readingWriting')),domains});
   const latest=resultsGate(state()).report;state().profile={...getProfile(),math:latest.math,readingWriting:latest.readingWriting,baseline:latest.total,total:goal,testDate:testDate||null};
   state().studio.preferences={scope,minutes:state().studio.preferences?.minutes||state().routine?.minutes||30,days:state().studio.preferences?.days||state().routine?.days||[1,2,3,4,5]};
   if(state().routine)state().routine.scope=scope;
   if(state().routine&&testDate)state().routine.testDate=testDate;else if(!testDate)state().routine=null;
   const scoreReports=state().studio.scoreReports;const row={date:report.date,math:report.math,readingWriting:report.readingWriting,label:report.source==='official-sat'?'Official SAT':'Bluebook practice'};
   if(!scoreReports.some(r=>r.date===row.date&&r.math===row.math&&r.readingWriting===row.readingWriting&&r.label===row.label))scoreReports.push(row);
   adding=false;save();render();window.scrollTo({top:0});toast('Official results saved. Your path now uses this evidence.');
  }catch(e){document.querySelector('#official-results-error').textContent=e.message;}return true;
 }
 return {gate,roadmap,settings,click,submit,isAdding:()=>adding,form,add:()=>{adding=true;location.hash='home';render();}};
}
